using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.Profiling;using Newtonsoft.Json.Linq;
public static class AuditGameStructure{
 public static string Main(){var scene=EditorSceneManager.GetActiveScene();var roots=scene.GetRootGameObjects();var objects=roots.SelectMany(r=>r.GetComponentsInChildren<Transform>(true)).ToArray();var renderers=roots.SelectMany(r=>r.GetComponentsInChildren<Renderer>(true)).ToArray();var components=roots.SelectMany(r=>r.GetComponentsInChildren<MonoBehaviour>(true)).Where(c=>c!=null).ToArray();var textures=Resources.FindObjectsOfTypeAll<Texture>();var report=new JObject{{"scene",scene.path},{"playing",Application.isPlaying},{"gameObjects",objects.Length},{"activeObjects",objects.Count(x=>x.gameObject.activeInHierarchy)},{"renderers",renderers.Length},{"activeRenderers",renderers.Count(r=>r.enabled&&r.gameObject.activeInHierarchy)},{"colliders",roots.Sum(r=>r.GetComponentsInChildren<Collider>(true).Length)},{"targetFrameRate",Application.targetFrameRate},{"vSync",QualitySettings.vSyncCount},{"quality",QualitySettings.names[QualitySettings.GetQualityLevel()]},{"roots",new JArray(roots.Select(r=>new JObject{{"name",r.name},{"active",r.activeSelf},{"objects",r.GetComponentsInChildren<Transform>(true).Length},{"renderers",r.GetComponentsInChildren<Renderer>(true).Length}}))},{"scripts",new JArray(components.GroupBy(c=>c.GetType().FullName).OrderByDescending(g=>g.Count()).Select(g=>new JObject{{"type",g.Key},{"count",g.Count()},{"active",g.Count(c=>c.isActiveAndEnabled)}}))},{"textures",new JArray(textures.OrderByDescending(t=>Profiler.GetRuntimeMemorySizeLong(t)).Take(30).Select(t=>new JObject{{"name",t.name},{"path",AssetDatabase.GetAssetPath(t)},{"width",t.width},{"height",t.height},{"bytes",Profiler.GetRuntimeMemorySizeLong(t)}}))},{"meshGroups",new JArray(renderers.Where(r=>r.enabled&&r.gameObject.activeInHierarchy).GroupBy(r=>r.sharedMaterial?.name??"null").OrderByDescending(g=>g.Count()).Take(30).Select(g=>new JObject{{"material",g.Key},{"count",g.Count()}}))}};Directory.CreateDirectory("Docs/Measurements/2026-10-03-performance");File.WriteAllText("Docs/Measurements/2026-10-03-performance/structure-"+scene.name+".json",report.ToString());return report.ToString();}
}
